select 
from marketing_tier

    del_flag = 0
    and tier_code = #{tierCode}
    and owner_type = #{ownerType}
    and owner_id = #{ownerId}
    and ticket_id = #{ticketId}
    and status = #{status}

order by owner_type asc, owner_id asc, ticket_id asc, min_quantity asc

select 
from marketing_tier
where owner_type = #{ownerType}
  and owner_id = #{ownerId}
  and ticket_id = #{ticketId}
  and min_quantity = #{minQuantity}
limit 1
